432	     * {@code '+61'} country code prepended. A valid result is a {@code '+'} followed by 8 to 15 digits,
433	     * and when the supplied country code is one with a known national-number length
434	     * ({@link #NATIONAL_NUMBER_LENGTHS}, e.g. {@code '+61'} => 9, {@code '+1'} => 10) the national
435	     * number must have exactly that many digits.
436	     *
437	     * @param telephone the raw telephone value, possibly {@code null}
438	     * @return the E.164 string, or {@code null} if the value is not a valid E.164 number
439	     */
440	    private String toE164(String telephone) {
441	        if (telephone == null) {
442	            return null;
443	        }
444	        String cleaned = telephone.replaceAll("[\\s()\\-]", "");
445	        boolean hasPlus = cleaned.startsWith("+");
446	        String digits = (hasPlus ? cleaned.substring(1) : cleaned).replaceAll("\\D", "");
447	        String nationalSignificant = hasPlus
448	            ? digits
449	            : "61" + (digits.startsWith("0") ? digits.substring(1) : digits);
450	        if (!nationalSignificant.matches("[0-9]{8,15}")) {
451	            return null;
452	        }
453	        if (!hasValidNationalNumberLength(nationalSignificant)) {
454	            return null;
455	        }
456	        return "+" + nationalSignificant;
457	    }
458	
459	    /**
460	     * Checks the national-number length of an E.164 number (country code plus national significant
461	     * digits, no leading {@code '+'}) against the per-country requirement in
462	     * {@link #NATIONAL_NUMBER_LENGTHS}. The longest listed country code that prefixes the number
463	     * selects the requirement, and the remaining digits must number exactly that many. A number whose
464	     * country code is not listed carries no per-country length requirement and is accepted.
465	     *
466	     * @param nationalSignificant the digits of the E.164 number, country code first, without the
467	     *                            leading {@code '+'}
468	     * @return {@code true} if the national-number length is correct for the country code, or the
469	     *         country code has no listed requirement; {@code false} otherwise
470	     */
471	    private boolean hasValidNationalNumberLength(String nationalSignificant) {
472	        String countryCode = NATIONAL_NUMBER_LENGTHS.keySet().stream()
473	            .filter(nationalSignificant::startsWith)
474	            .max(Comparator.comparingInt(String::length))
475	            .orElse(null);
476	        if (countryCode == null) {
477	            return true;
478	        }
479	        int nationalLength = nationalSignificant.length() - countryCode.length();
480	        return nationalLength == NATIONAL_NUMBER_LENGTHS.get(countryCode);
481	    }
482	
483	    /**
484	     * Normalizes an optional owner email address. A {@code null} value means the field was omitted and
485	     * is left unset. When a value is present it must be a syntactically valid address; the stored and
486	     * returned value is that address lower-cased.
487	     *
488	     * @param email the raw email value submitted by the client, or {@code null} if omitted
489	     * @return the lower-cased email, or {@code null} if none was supplied
490	     * @throws InvalidOwnerFieldsException if a value is present but not a syntactically valid address,
491	     *                                     yielding a 400 response
492	     */
493	    private String normalizeEmail(String email) {
494	        if (email == null) {
495	            return null;
496	        }
497	        if (!EMAIL_PATTERN.matcher(email).matches()) {
498	            throw new InvalidOwnerFieldsException(List.of("email"));
499	        }
500	        return email.toLowerCase(Locale.ROOT);
501	    }
502	
503	    /**
504	     * Counts the existing owners that, before this create, already share the given first name and
505	     * last name. Both names are compared case-insensitively with surrounding and internal whitespace
506	     * collapsed, consistent with the other owner-name comparisons. The owner being created has not
507	     * been saved yet, so it is never included in the count.
508	     *
509	     * @param firstName the first name of the owner being created
510	     * @param lastName  the last name of the owner being created
511	     * @return the number of existing owners sharing both names
512	     */
513	    private int countNamesakes(String firstName, String lastName) {
514	        String normalizedFirstName = normalizeForComparison(firstName);
515	        String normalizedLastName = normalizeForComparison(lastName);
516	        return (int) this.clinicService.findAllOwners().stream()
517	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
518	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
519	            .count();
520	    }
521	
522	    /**
523	     * Builds the owner's {@code customerCode}, formatted {@code '<REGION>-<HASH8>'}. {@code REGION} is
524	     * the region code derived from the owner's postcode ({@link #regionForPostcode}, {@code 'UNKNOWN'}
525	     * when the postcode is absent or in no known range), and {@code HASH8} is the first eight
526	     * upper-cased hex characters of the SHA-256 digest of the owner's normalized telephone followed by
527	     * the last name (e.g. {@code 'NSW-1A2B3C4D'}). The identity carries no sequence number, so the
528	     * same postcode region, telephone and last name always yield the same customer code.
529	     *
530	     * @param postcode  the owner's validated postcode, or {@code null} if none was supplied
531	     * @param telephone the owner's normalized (E.164) telephone
532	     * @param lastName  the owner's last name
533	     * @return the formatted customer code
534	     */
535	    private String generateCustomerCode(String postcode, String telephone, String lastName) {
536	        String region = regionForPostcode(postcode);
537	        String hash8 = hashHex(telephone + lastName, 8);
538	        return region + "-" + hash8;
539	    }
540	
541	    /**
542	     * Resolves the region code for a postcode by its known 4-digit range in {@link #REGION_POSTCODES}
543	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}), returning {@code 'UNKNOWN'}
544	     * when the postcode is {@code null}, not exactly 4 digits, or falls in no known range. This is the
545	     * {@code <REGION>} segment baked into the {@code customerCode}.
546	     *
547	     * @param postcode the owner's postcode, or {@code null}
548	     * @return the region code, or {@code 'UNKNOWN'}
549	     */
550	    private String regionForPostcode(String postcode) {
551	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
552	            return "UNKNOWN";
553	        }
554	        int value = Integer.parseInt(postcode);
555	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
556	            int[] range = entry.getValue();
557	            if (value >= range[0] && value <= range[1]) {
558	                return entry.getKey();
559	            }
560	        }
561	        return "UNKNOWN";
562	    }
563	
564	    /**
565	     * Resolves the region code for a city via the fixed {@link #CITY_REGION} table
566	     * ({@code Sydney->NSW}, {@code Melbourne->VIC}, {@code Brisbane->QLD}), returning {@code 'UNKNOWN'}
567	     * when the city is not listed. Used to validate an owner's optional postcode against its city's
568	     * region.
569	     *
570	     * @param city the owner's city
571	     * @return the region code, or {@code 'UNKNOWN'}
572	     */
573	    private String regionForCity(String city) {
574	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
575	    }
576	
577	    /**
578	     * Returns the first {@code length} upper-cased hex characters of the SHA-256 digest of the given
579	     * input. Used for the {@code <HASH8>} segment of a {@code customerCode} (length 8) and for the
580	     * deterministic {@code householdId} (length 12).
581	     *
582	     * @param input  the value to hash
583	     * @param length the number of leading hex characters to return
584	     * @return the first {@code length} upper-cased hex characters of its SHA-256 digest
585	     */
586	    private String hashHex(String input, int length) {
587	        try {
588	            byte[] digest = MessageDigest.getInstance("SHA-256")
589	                .digest(input.getBytes(StandardCharsets.UTF_8));
590	            StringBuilder hex = new StringBuilder(digest.length * 2);
591	            for (byte b : digest) {
592	                hex.append(String.format("%02x", b));
593	            }
594	            return hex.substring(0, length).toUpperCase(Locale.ROOT);
595	        } catch (NoSuchAlgorithmException e) {
596	            throw new IllegalStateException("SHA-256 algorithm not available", e);
597	        }
598	    }
599	
600	    /**
601	     * Counts the existing owners already in the given city, used to derive the per-city sequence of a
602	     * {@code customerCode}. Cities are compared case-insensitively with surrounding and internal
603	     * whitespace collapsed, consistent with the other owner-field comparisons. The owner being created
604	     * has not been saved yet, so it is never included in the count.
605	     *
606	     * @param city the city of the owner being created
607	     * @return the number of existing owners in that city
608	     */
609	    private int countOwnersInCity(String city) {
610	        String normalizedCity = normalizeForComparison(city);
611	        return (int) this.clinicService.findAllOwners().stream()
612	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
613	            .count();
614	    }
615	
616	    /**
617	     * Rejects creation of an owner whose city already contains the maximum number of owners
618	     * ({@value #CITY_CAPACITY}). Owners are counted per city case-insensitively with surrounding and
619	     * internal whitespace collapsed, consistent with the other owner-field comparisons.
620	     *
621	     * @param city the city of the owner being created
622	     * @throws OwnerCityAtCapacityException if the city already contains {@value #CITY_CAPACITY} or more
623	     *                                      owners, yielding a 409 Conflict response
624	     */
625	    private void rejectCityAtCapacity(String city) {
626	        if (countOwnersInCity(city) >= CITY_CAPACITY) {
627	            throw new OwnerCityAtCapacityException(city);
628	        }
629	    }
630	
631	    /**
632	     * Rejects creation of an owner once the given business day has already reached its daily quota
633	     * of {@value #DAILY_OWNER_LIMIT} owners. Owners are counted by their {@code registrationDate}
634	     * being that day — the adjusted business day the owner being created will carry — so the quota
635	     * applies per business day. The owner being created has not been saved yet, so it is never
636	     * included in the count.
637	     *
638	     * @param registrationDate the adjusted business-day registration date of the owner being created
639	     * @throws DailyOwnerLimitReachedException if {@value #DAILY_OWNER_LIMIT} or more owners already
640	     *                                         carry that registration date, yielding a
641	     *                                         429 Too Many Requests response
642	     */
643	    private void rejectDailyLimitReached(LocalDate registrationDate) {
644	        if (countOwnersRegisteredOn(registrationDate) >= DAILY_OWNER_LIMIT) {
645	            throw new DailyOwnerLimitReachedException(registrationDate);
646	        }
647	    }
648	
649	    /**
650	     * Counts the existing owners that carry the given day as their {@code registrationDate} — the same
651	     * per-business-day bucket the daily create-limit and the bulk-signup warning both accumulate over.
652	     *
653	     * @param registrationDate the business day to count owners for
654	     * @return the number of existing owners registered on that day
655	     */
656	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
657	        return this.clinicService.findAllOwners().stream()
658	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
659	            .count();
660	    }
661	
662	    /**
663	     * Sets the {@code bulkSignupWarning} flag on an owner response. The flag is {@code true} when more
664	     * than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the current business day's
665	     * {@code registrationDate} — the business day a create would land on right now — and {@code false}
666	     * otherwise.
667	     *
668	     * @param ownerDto the owner response to flag
669	     */
670	    private void applyBulkSignupWarning(OwnerDto ownerDto) {
671	        LocalDate today = toBusinessDay(LocalDate.now());
672	        ownerDto.setBulkSignupWarning(countOwnersRegisteredOn(today) > BULK_SIGNUP_WARNING_THRESHOLD);
673	    }
674	
675	    /**
676	     * Rolls a registration date forward to a business day. A date that falls on a Saturday or Sunday
677	     * is rolled forward to the next Monday; a date already on a weekday is returned unchanged. This
678	     * applies to the effective registration date whether it was supplied in the request or defaulted
679	     * to the server date, and the adjusted value is what gets stored as {@code registrationDate} and
680	     * feeds every value derived from it (such as the membership number's year segment and the daily
681	     * create-limit's per-day bucket).
682	     *
683	     * @param date the effective registration date, supplied or defaulted
684	     * @return the same date when it is a weekday, otherwise the next Monday
685	     */
686	    private LocalDate toBusinessDay(LocalDate date) {
687	        LocalDate adjusted = date;
688	        while (adjusted.getDayOfWeek() == DayOfWeek.SATURDAY
689	            || adjusted.getDayOfWeek() == DayOfWeek.SUNDAY) {
690	            adjusted = adjusted.plusDays(1);
691	        }
692	        return adjusted;
693	    }
694	
695	    /**
696	     * Rejects creation of an owner whose derived {@code identityKey} exactly matches an existing
697	     * owner's. The identity key — {@code '<normalizedTelephone>|<email or empty>|<householdId or
698	     * empty>'} — is the single value that consolidates all duplicate detection: the previously
699	     * separate telephone, email and household checks are all expressed through it. Because the
700	     * telephone is part of the key, two members of the same household (same {@code householdId})
701	     * with different telephones have different identity keys and are both allowed; only a whole-key
702	     * match is a duplicate. The owner being created already carries its normalized telephone,
703	     * email and (if any) household id, and existing owners store the same normalized forms, so the
704	     * keys are compared directly.
705	     *
706	     * @param owner the owner being created, with its telephone, email and household id already set
707	     * @throws DuplicateOwnerIdentityException if another owner already has the same identity key,
708	     *                                         yielding a 409 Conflict response
709	     */
710	    private void rejectDuplicateIdentity(Owner owner) {
711	        String identityKey = owner.getIdentityKey();
712	        boolean inUse = this.clinicService.findAllOwners().stream()
713	            .map(Owner::getIdentityKey)
714	            .anyMatch(identityKey::equals);
715	        if (inUse) {
716	            throw new DuplicateOwnerIdentityException(identityKey);
717	        }
718	    }
719	
720	    /**
721	     * Flags the owner being created as a possible (soft) duplicate. A possible duplicate is an owner
722	     * that is not a hard duplicate (its identity key is unique, so it has already passed
723	     * {@link #rejectDuplicateIdentity}) yet belongs to the same household as an existing owner — that
724	     * is, it carries the same computed {@code householdId} (derived from the last name and postcode) —
725	     * while carrying a different telephone. When such a match exists the owner is created with
726	     * {@code possibleDuplicate} set to {@code true} and {@code possibleDuplicateOf} set to the matching
727	     * owner's id (the earliest matching owner by id); otherwise {@code possibleDuplicate} is
728	     * {@code false} and {@code possibleDuplicateOf} is left unset.
729	     *
730	     * <p>An owner that declares household membership via {@code sharesHousehold} is never flagged: a
731	     * declared household member is not a suspected duplicate. (Without that declaration a same-household
732	     * owner is rejected outright by {@link #rejectHouseholdDuplicate}, so no suspected-duplicate match
733	     * survives for a created owner either.)
734	     *
735	     * @param owner           the owner being created, with its household id and telephone already set
736	     * @param sharesHousehold whether the owner declared itself a member of an existing household
737	     */
738	    private void applyPossibleDuplicate(Owner owner, boolean sharesHousehold) {
739	        owner.setPossibleDuplicate(false);
740	        if (sharesHousehold) {
741	            return;
742	        }
743	        String householdId = owner.getHouseholdId();
744	        if (householdId == null || householdId.isBlank()) {
745	            return;
746	        }
747	        String telephone = owner.getTelephone();
748	        Owner match = this.clinicService.findAllOwners().stream()
749	            .filter(existing -> householdId.equals(existing.getHouseholdId())
750	                && !Objects.equals(telephone, existing.getTelephone()))
751	            .min(Comparator.comparingInt(Owner::getId))
752	            .orElse(null);
753	        if (match != null) {
754	            owner.setPossibleDuplicate(true);
755	            owner.setPossibleDuplicateOf(match.getId());
756	        }
757	    }
758	
759	    /**
760	     * Computes the owner's deterministic {@code householdId}: the first twelve upper-cased hex
761	     * characters of the SHA-256 digest of the normalized last name and the postcode joined by a
762	     * {@code '|'}. Because the value derives only from the last name and postcode, every owner that
763	     * shares both automatically shares the same household id, so the household is keyed on
764	     * {@code (lastName, postcode)} with no opt-in required. The last name is normalized for comparison
765	     * (trimmed, internal whitespace collapsed, lower-cased) so values differing only in case or spacing
766	     * still land in the same household.
767	     *
768	     * @param lastName the owner's last name
769	     * @param postcode the owner's validated postcode, or {@code null} if none was supplied
770	     * @return the derived household id, or {@code null} when the owner has no postcode and so belongs
771	     *         to no postcode-keyed household
772	     */
773	    private String computeHouseholdId(String lastName, String postcode) {
774	        if (postcode == null) {
775	            return null;
776	        }
777	        return hashHex(normalizeForComparison(lastName) + "|" + postcode, 12);
778	    }
779	
780	    /**
781	     * Rejects creation of an owner that would join an existing household it has not declared membership
782	     * of. The household is keyed on the computed {@code householdId} (derived from the last name and
783	     * postcode), so any existing owner carrying the same {@code householdId} is a member of the same
784	     * household. A second owner in that household is a household duplicate and is rejected with a
785	     * {@code 409 Conflict} unless the request opts in via {@code sharesHousehold}, in which case this
786	     * check is bypassed and the owner is created as a declared household member. An owner with no
787	     * {@code householdId} (no postcode) belongs to no household and is never rejected here.
788	     *
789	     * @param owner the owner being created, with its household id already computed
790	     * @throws DuplicateHouseholdException if an existing owner already belongs to the same
791	     *                                     household, yielding a 409 Conflict response
792	     */
793	    private void rejectHouseholdDuplicate(Owner owner) {
794	        String householdId = owner.getHouseholdId();
795	        if (householdId == null || householdId.isBlank()) {
796	            return;
797	        }
798	        boolean inUse = this.clinicService.findAllOwners().stream()
799	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
800	        if (inUse) {
801	            throw new DuplicateHouseholdException(householdId);
802	        }
803	    }
804	
805	    /**
806	     * Normalizes a text value for case- and whitespace-insensitive comparison: surrounding
807	     * whitespace is trimmed, every internal run of whitespace is collapsed to a single space, and
808	     * the result is lower-cased.
809	     *
810	     * @param value the value to normalize, possibly {@code null}
811	     * @return the normalized value, or an empty string if {@code value} is {@code null}
812	     */
813	    private String normalizeForComparison(String value) {
814	        if (value == null) {
815	            return "";
816	        }
817	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
818	    }
819	
820	    /**
821	     * Normalizes an owner address for storage, display and comparison. Surrounding whitespace is
822	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
823	     * upper-cased, and common street-type abbreviations appearing as whole tokens are expanded
824	     * ({@code ST} to {@code STREET}, {@code RD} to {@code ROAD}, {@code AVE} to {@code AVENUE}).
825	     * This normalized value is what gets stored and returned.
826	     *
827	     * @param address the raw address value submitted by the client, possibly {@code null}
828	     * @return the normalized address, or an empty string if {@code address} is {@code null}
829	     */
830	    private String normalizeAddress(String address) {
831	        if (address == null) {
832	            return "";
833	        }
834	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
835	        if (collapsed.isEmpty()) {
836	            return collapsed;
837	        }
838	        String[] tokens = collapsed.split(" ");
839	        StringBuilder normalized = new StringBuilder(collapsed.length());
840	        for (int i = 0; i < tokens.length; i++) {
841	            if (i > 0) {
842	                normalized.append(' ');
843	            }
844	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
845	        }
846	        return normalized.toString();
847	    }
848	}
